use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|j: int| 0 <= j < result.len() ==> result[j] == 1,
{
    let n = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == 1,
        decreases n - i
    {
        result.push(1);

        // After push, length increased by 1 and the new last element is 1.
        assert(result.len() == i + 1);
        assert(result[i as int] == 1);
        assert(forall|j: int| 0 <= j < i ==> result[j] == 1);

        i += 1;

        // Re-establish invariants for the next loop iteration.
        assert(result.len() == i);
        assert(forall|j: int| 0 <= j < i ==> result[j] == 1);
    }

    result
}

} // verus!